<template>
  <div class="mode-wrap">
    <div class="mode-bg"></div>

    <div class="slide-scroll">
      <div class="slide-inner">
        <h1 class="main-title">Выбор режима</h1>
        <p class="sub-title">В каком режиме вы хотите продолжить?</p>

        <div class="modes-row">
          <div
            class="mode-card mode-card-sim"
            :class="{ selected: selectedMode === 'simulator' }"
            @click="selectedMode = 'simulator'"
          >
            <div class="mode-card-icon-wrap mode-icon-sim">
              <img :src="chartIcon" class="mode-card-icon" alt="">
            </div>
            <div class="mode-card-title">Режим симулятора</div>
            <div class="mode-card-desc">Торгуйте без заданных сценариев и условий. Ваш стартовый капитал - $3&nbsp;000&nbsp;000. Выберите тактику и за 10 сделок постарайтесь заработать как можно больше.</div>
          </div>

          <div
            class="mode-card mode-card-cases"
            :class="{ selected: selectedMode === 'cases' }"
            @click="selectedMode = 'cases'"
          >
            <div class="mode-card-icon-wrap mode-icon-cases">
              <img :src="chartIcon" class="mode-card-icon" alt="">
            </div>
            <div class="mode-card-title">Режим кейсов</div>
            <div class="mode-card-desc">Протестируйте стратегию в трёх сценариях: удержать прибыль, начать с нуля и выйти из убытка. Ваш стартовый капитал - $3&nbsp;000&nbsp;000. К нему добавляется прибыль по условиям кейсов. В каждом кейсе - 10 сделок.</div>
          </div>
        </div>
      </div>
    </div>

    <div class="slide-footer">
      <button class="nav-btn" @click="goBack">Назад</button>
      <button class="nav-btn nav-btn-primary" :disabled="!selectedMode" @click="confirmMode">Играть</button>
    </div>
  </div>
</template>

<script>
import chartIcon from '@/assets/icons/chart.png'

export default {
  name: 'ModeSelectView',
  data() { return { chartIcon, selectedMode: null } },
  mounted() {
    const hasResult = localStorage.getItem('hasResult') === 'true'
    if (hasResult) this.$router.push('/res')
  },
  methods: {
    goBack() {
      localStorage.removeItem('levelEnded')
      this.$router.push('/select')
    },
    confirmMode() {
      if (!this.selectedMode) return
      if (this.selectedMode === 'simulator') this.selectSimulator()
      else this.selectCases()
    },
    selectSimulator() {
      const asset = localStorage.getItem('selectedAsset')
      localStorage.clear()
      localStorage.setItem('selectedAsset', asset)
      localStorage.setItem('gameMode', 'simulator')
      localStorage.setItem('level', '4')
      this.$router.push('/play')
    },
    selectCases() {
      const asset = localStorage.getItem('selectedAsset')
      localStorage.clear()
      localStorage.setItem('selectedAsset', asset)
      localStorage.setItem('gameMode', 'cases')
      localStorage.setItem('level', '1')
      this.$router.push('/cases')
    }
  }
}
</script>

